  Instrument(
    id: 'mesa-traccion-ortopedica',
    isNew: true,
    name: LocalizedText(ca: 'Taula de tracció ortopèdica (taula de fractures)', es: 'Mesa de tracción ortopédica (mesa de fracturas)', en: 'Orthopedic traction table (fracture table)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Fracture table', 'Hana table'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Taula quirúrgica especialitzada amb suports per a les cames que permeten aplicar i mantenir tracció longitudinal de manera controlada durant la intervenció.',
      es: 'Mesa quirúrgica especializada con soportes para las piernas que permiten aplicar y mantener tracción longitudinal de forma controlada durante la intervención.',
      en: 'A specialized operating table with leg supports that allow controlled longitudinal traction to be applied and maintained throughout the procedure.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia de fractures de fèmur i maluc (p. ex. enclavat endomedul·lar, artroplàstia per via anterior) per facilitar la reducció indirecta i mantenir-la durant el procediment.',
      es: 'Se utiliza en cirugía de fracturas de fémur y cadera (p. ej. enclavado endomedular, artroplastia por vía anterior) para facilitar la reducción indirecta y mantenerla durante el procedimiento.',
      en: 'Used in femur and hip fracture surgery (e.g. intramedullary nailing, anterior-approach arthroplasty) to facilitate indirect fracture reduction and maintain it throughout the procedure.',
    ),
    tip: LocalizedText(
      ca: 'Les taules de tracció poden provocar lesió per pressió al perineu o lesió nerviosa per estirament si no es vigila amb cura la posició i la força de tracció.',
      es: 'Las mesas de tracción pueden provocar lesión por presión en el periné o lesión nerviosa por estiramiento si no se vigila con cuidado la posición y la fuerza de tracción.',
      en: 'Traction tables can cause pressure injury to the perineum or nerve stretch injury if positioning and traction force are not checked carefully.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/2/23/US_Navy_090508-N-5234F-068_Dr._K.K._Singh%2C_center%2C_an_orthopedic_surgeon_consultant_at_Mount_St._Johns_Hospital%2C_examines_a_fracture_table_donated_through_Continuing_Promise_2009.jpg',
