  Instrument(
    id: 'arco-c',
    isNew: true,
    name: LocalizedText(ca: 'Arc en C (fluoroscòpia intraoperatòria)', es: 'Arco en C (fluoroscopia intraoperatoria)', en: 'C-arm (intraoperative fluoroscopy)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['C-arm fluoroscope', 'Mobile fluoroscopy unit'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip de raigs X mòbil amb un braç en forma de C que allotja l\'emissor i el detector d\'imatge en extrems oposats, i que permet obtenir imatges en temps real.',
      es: 'Equipo de rayos X móvil con un brazo en forma de C que aloja el emisor y el detector de imagen en extremos opuestos, y que permite obtener imágenes en tiempo real.',
      en: 'A mobile X-ray unit with a C-shaped arm holding the emitter and image detector at opposite ends, providing real-time imaging.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza durant la cirurgia per comprovar en temps real la reducció de la fractura, la posició dels implants (claus, plaques, cargols) i l\'alineació òssia.',
      es: 'Se utiliza durante la cirugía para comprobar en tiempo real la reducción de la fractura, la posición de los implantes (clavos, placas, tornillos) y la alineación ósea.',
      en: 'Used during surgery to check fracture reduction, implant position (nails, plates, screws) and bone alignment in real time.',
    ),
    tip: LocalizedText(
      ca: 'Com que utilitza radiació ionitzant, l\'equip quirúrgic aplica mesures de temps, distància i protecció (davantals i protectors tiroidals de plom) per minimitzar l\'exposició quan calen diverses exposicions seguides.',
      es: 'Como utiliza radiación ionizante, el equipo quirúrgico aplica medidas de tiempo, distancia y protección (delantales y protectores tiroideos de plomo) para minimizar la exposición cuando hacen falta varias exposiciones seguidas.',
      en: 'Because it uses ionizing radiation, staff follow time, distance and shielding practices (lead aprons, thyroid shields) to minimize exposure when several exposures are needed in a row.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/82/New_Alma_Hospital_Mannarkkad_orthopaedic_OT_laminar_flow_C-arm.jpg',
      license: 'CC0 1.0 Universal (Public Domain Dedication)',
      attribution: 'Drnabeelmohdkk1, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:New_Alma_Hospital_Mannarkkad_orthopaedic_OT_laminar_flow_C-arm.jpg',
    ),
  ),

