  Instrument(
    id: 'separador-cerebral-autoestatico',
    isNew: true,
    name: LocalizedText(ca: 'Separador cerebral autoestàtic (sistema Leyla/Greenberg)', es: 'Separador cerebral autoestático (sistema Leyla/Greenberg)', en: 'Self-retaining brain retractor system (Leyla/Greenberg)'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.neurocirugia,
    aliases: ['Leyla retractor', 'Greenberg retractor', 'brain spatula holder', 'retractor cerebral flexible'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Sistema format per una base de fixació ancorada al cap del pacient o al capçal craneal, braços articulats o flexibles i una o diverses pales (espàtules) mal·leables que sostenen el teixit cerebral un cop col·locades.',
      es: 'Sistema compuesto por una base de fijación anclada a la cabeza del paciente o al cabezal craneal, brazos articulados o flexibles y una o varias palas (espátulas) maleables que sostienen el tejido cerebral una vez colocadas.',
      en: 'A system made of a fixation base anchored either to the patient\'s own head or to a separate cranial frame, articulated or flexible arms, and one or more malleable blades (spatulas) that hold back brain tissue once positioned.',
    ),
    use: LocalizedText(
      ca: 'Proporciona una retracció cerebral estable i "sense mans" durant la resecció de tumors, el clipatge d\'aneurismes, la descompressió microvascular i altres abordatges intracranials i de base de crani perllongats.',
      es: 'Proporciona una retracción cerebral estable y "sin manos" durante la resección de tumores, el clipaje de aneurismas, la descompresión microvascular y otros abordajes intracraneales y de base de cráneo prolongados.',
      en: 'Provides stable, hands-free brain retraction during tumor resection, aneurysm clipping, microvascular decompression and other prolonged intracranial and skull-base approaches.',
    ),
  ),
