  Instrument(
    id: 'bomba-circulacion-extracorporea',
    isNew: true,
    name: LocalizedText(ca: 'Bomba de circulació extracorpòria', es: 'Bomba de circulación extracorpórea', en: 'Heart-lung machine'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.cardiovascular,
    aliases: ['Heart-lung machine', 'Cardiopulmonary bypass machine', 'CPB machine', 'Máquina de circulación extracorpórea', 'Bomba de CEC'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Consola amb bombes (centrífugues o de rodet) i un circuit extracorpori que substitueix temporalment la funció de bombeig del cor i d\'intercanvi gasós dels pulmons durant la cirurgia a cor obert.',
      es: 'Consola con bombas (centrífugas o de rodillo) y un circuito extracorpóreo que sustituye temporalmente la función de bombeo del corazón y de intercambio gaseoso de los pulmones durante la cirugía a corazón abierto.',
      en: 'A console with pumps (centrifugal or roller) and an extracorporeal circuit that temporarily replaces the pumping function of the heart and the gas-exchange function of the lungs during open-heart surgery.',
    ),
    use: LocalizedText(
      ca: 'Manté la circulació i l\'oxigenació de la sang mentre el cor està aturat i obert, fent possible procediments com la revascularització coronària o la cirurgia valvular.',
      es: 'Mantiene la circulación y la oxigenación de la sangre mientras el corazón está detenido y abierto, haciendo posible procedimientos como la revascularización coronaria o la cirugía valvular.',
      en: 'It maintains blood circulation and oxygenation while the heart is stopped and open, making procedures such as coronary revascularization or valve surgery possible.',
    ),
    tip: LocalizedText(
      ca: 'Sempre el controla un perfusionista, que n\'ajusta el flux, la pressió i la temperatura en coordinació constant amb el cirurgià i l\'anestesiòleg.',
      es: 'Siempre lo controla un perfusionista, que ajusta el flujo, la presión y la temperatura en coordinación constante con el cirujano y el anestesiólogo.',
      en: 'It is always operated by a cardiac perfusionist, who adjusts flow, pressure and temperature in constant coordination with the surgeon and anesthesiologist.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/f/f2/Heart-lung-machine.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Jörg Schulze (Schulli), via Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Heart-lung-machine.jpg',
    ),
  ),
