  Instrument(
    id: 'litotriptor-neumatico',
    isNew: true,
    name: LocalizedText(ca: 'Litotritor pneumàtic (balístic) intracorpori', es: 'Litotritor neumático (balístico) intracorpóreo', en: 'Pneumatic (ballistic) intracorporeal lithotripter'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.urologia,
    aliases: ['Swiss LithoClast', 'Pneumatic lithotripter', 'Ballistic lithotripsy probe'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Peça de mà accionada per aire comprimit que transmet una sèrie ràpida de polsos mecànics de xoc a través d\'una sonda rígida prima en contacte directe amb el càlcul.',
      es: 'Pieza de mano accionada por aire comprimido que transmite una serie rápida de pulsos mecánicos de choque a través de una sonda rígida fina en contacto directo con el cálculo.',
      en: 'A compressed-air-driven handpiece that transmits a rapid series of mechanical shock pulses through a thin rigid probe held in direct contact with the stone.',
    ),
    use: LocalizedText(
      ca: 'Fragmenta càlculs urinaris (renals, ureterals o vesicals) sota visió endoscòpica directa durant una NLP, ureteroscòpia o cistolitolapaxia; sovint es combina amb una sonda ultrasònica en equips moderns.',
      es: 'Fragmenta cálculos urinarios (renales, ureterales o vesicales) bajo visión endoscópica directa durante una NLP, ureteroscopia o cistolitolapaxia; a menudo se combina con una sonda ultrasónica en equipos modernos.',
      en: 'Fragments urinary stones (renal, ureteral or bladder) under direct endoscopic vision during PCNL, ureteroscopy or cystolitholapaxy; often combined with an ultrasonic probe in modern combination devices.',
    ),
  ),
  Instrument(
    id: 'cesta-litiasis-dormia',
    isNew: true,
    name: LocalizedText(ca: 'Cistella de litiasi (cistella de Dormia)', es: 'Cesta de litiasis (cesta de Dormia)', en: 'Stone retrieval basket (Dormia basket)'),
    category: InstrumentCategory.accesos,
    specialty: Specialty.urologia,
    aliases: ['Dormia basket', 'Stone retrieval basket', 'Nitinol stone basket'],
    icon: 'bolt',
    description: LocalizedText(
