  Instrument(
    id: 'ecobroncoscopio-ebus',
    isNew: true,
    name: LocalizedText(ca: 'Ecobroncoscopi EBUS', es: 'Ecobroncoscopio EBUS', en: 'EBUS endobronchial ultrasound bronchoscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.toracica,
    aliases: ['Endobronchial ultrasound bronchoscope', 'EBUS-TBNA scope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Videobroncoscopi flexible amb un transductor d\'ultrasons convex o radial integrat a la punta, que permet la punció-aspiració transbronquial amb agulla (PAAF) guiada per ecografia de ganglis mediastínics/hiliars i lesions centrals.',
      es: 'Videobroncoscopio flexible con un transductor de ultrasonidos convexo o radial integrado en la punta, que permite la punción-aspiración transbronquial con aguja (PAAF) guiada por ecografía de ganglios mediastínicos/hiliares y lesiones centrales.',
      en: 'Flexible video-bronchoscope with an integrated convex or radial ultrasound transducer at the tip, allowing real-time ultrasound-guided transbronchial needle aspiration (TBNA) of mediastinal/hilar lymph nodes and central lesions.',
    ),
    use: LocalizedText(
      ca: 'Estadificació ganglionar mediastínica mínimament invasiva en el càncer de pulmó, com a alternativa o complement a la mediastinoscòpia quirúrgica ja catalogada.',
      es: 'Estadificación ganglionar mediastínica mínimamente invasiva en el cáncer de pulmón, como alternativa o complemento a la mediastinoscopia quirúrgica ya catalogada.',
      en: 'Minimally invasive mediastinal lymph node staging in lung cancer, as an alternative or complement to the already-catalogued surgical mediastinoscopy.',
    ),
    tip: LocalizedText(
      ca: 'El rendiment diagnòstic de la punció guiada per EBUS és comparable al de la mediastinoscòpia; aquesta darrera ara es reserva per als casos amb EBUS negatiu però sospita alta de malignitat.',
      es: 'El rendimiento diagnóstico de la punción guiada por EBUS es comparable al de la mediastinoscopia; esta última ahora se reserva para los casos con EBUS negativo pero sospecha alta de malignidad.',
      en: 'EBUS-guided puncture has diagnostic yield comparable to mediastinoscopy, which is now reserved for cases where EBUS is negative but malignancy suspicion remains high.',
    ),
  ),
  Instrument(
    id: 'grapadora-circular-eea',
    isNew: true,
    name: LocalizedText(ca: 'Grapadora circular EEA', es: 'Grapadora circular EEA', en: 'Circular (EEA) stapler'),
    category: InstrumentCategory.sutura,
    specialty: Specialty.toracica,
    aliases: ['EEA circular stapler'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu de grapat circular amb enclusa desmuntable, introduït per via transoral o a través del mussol esofàgic o gàstric resecat, que crea una anastomosi esofagogàstrica circular grapada; diferent de la grapadora toràcica motoritzada ja catalogada, que grapa el parènquima/vasos/bronqui, no l\'esòfag.',
      es: 'Dispositivo de grapado circular con yunque desmontable, introducido por vía transoral o a través del muñón esofágico o gástrico resecado, que crea una anastomosis esofagogástrica circular grapada; distinto de la grapadora torácica motorizada ya catalogada, que grapa el parénquima/vasos/bronquio, no el esófago.',
      en: 'Circular stapling device with a detachable anvil, inserted transorally or through the resected esophageal/gastric stump, creating a circular stapled esophagogastric anastomosis; distinct from the already-catalogued motorized thoracic stapler, which staples lung parenchyma/vessels/bronchus, not the esophagus.',
    ),
    use: LocalizedText(
      ca: 'Anastomosi esofagogàstrica durant una esofagectomia (p. ex. tècnica d\'Ivor Lewis).',
      es: 'Anastomosis esofagogástrica durante una esofagectomía (p. ej. técnica de Ivor Lewis).',
      en: 'Esophagogastric anastomosis during esophagectomy (e.g. Ivor Lewis procedure).',
    ),
  ),
  Instrument(
    id: 'sistema-fijacion-costal',
    isNew: true,
    name: LocalizedText(ca: 'Sistema de fixació costal (placa d\'osteosíntesi)', es: 'Sistema de fijación costal (placa de osteosíntesis)', en: 'Rib fixation plate system'),
