  Instrument(
    id: 'calentador-fluidos-iv',
    name: LocalizedText(ca: 'Escalfador de fluids intravenosos', es: 'Calentador de fluidos intravenosos', en: 'IV fluid (and blood) warmer'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['Fluid warmer', 'Blood warmer'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu que escalfa sèrums i hemoderivats a 37-41°C abans de la seva infusió, mitjançant un bescanviador de calor en línia; diferent de la manta d\'aire forçat ja catalogada, que escalfa el pacient per convecció en comptes dels fluids.',
      es: 'Dispositivo que calienta sueros y hemoderivados a 37-41°C antes de su infusión, mediante intercambiador de calor en línea; distinto de la manta de aire forzado ya catalogada, que calienta al paciente por convección en vez de los fluidos.',
      en: 'A device that heats fluids and blood products to 37-41°C before infusion, via an in-line heat exchanger; distinct from the forced-air warming blanket already catalogued, which warms the patient by convection rather than the fluids.',
    ),
    use: LocalizedText(
      ca: 'Prevenció de la hipotèrmia perioperatòria inadvertida, especialment en cirurgia llarga o amb grans volums de fluidoteràpia.',
      es: 'Prevención de la hipotermia perioperatoria inadvertida, especialmente en cirugía larga o con grandes volúmenes de fluidoterapia.',
