  Instrument(
    id: 'monitor-gasto-cardiaco-contorno-pulso',
    name: LocalizedText(ca: 'Monitor de cabal cardíac per contorn de pols', es: 'Monitor de gasto cardíaco por contorno de pulso', en: 'Pulse-contour cardiac output monitor'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.anestesiologiaReanimacio,
    aliases: ['FloTrac/Vigileo', 'Pulse-contour cardiac output monitor'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema de monitorització hemodinàmica mínimament invasiva que calcula el cabal cardíac, el volum sistòlic i les seves variacions a partir de l\'anàlisi del contorn de l\'ona de pressió arterial, sense necessitat de catèter venós central ni calibratge extern; a diferència del catèter de Swan-Ganz ja catalogat, només requereix una via arterial.',
      es: 'Sistema de monitorización hemodinámica mínimamente invasiva que calcula gasto cardíaco, volumen sistólico y sus variaciones a partir del análisis del contorno de la onda de presión arterial, sin necesidad de catéter venoso central ni calibración externa; a diferencia del catéter de Swan-Ganz ya catalogado, solo requiere una vía arterial.',
      en: 'A minimally invasive hemodynamic monitoring system that calculates cardiac output, stroke volume, and their variations from the arterial pressure waveform contour, without needing a central venous catheter or external calibration; unlike the Swan-Ganz catheter already catalogued, it only requires an arterial line.',
    ),
    use: LocalizedText(
      ca: 'Fluidoteràpia dirigida per objectius en cirurgia d\'alt risc, utilitzant només una via arterial (complementa el catèter arterial ja catalogat).',
      es: 'Fluidoterapia dirigida por objetivos (goal-directed therapy) en cirugía de alto riesgo, usando solo una vía arterial (complementa el catéter arterial ya catalogado).',
      en: 'Goal-directed fluid therapy in high-risk surgery, using only an arterial line (complements the arterial catheter already catalogued).',
    ),
    tip: LocalizedText(
      ca: 'Destaca per la seva facilitat de maneig per part d\'infermeria i el seu ús fora de UCI, però té menor fiabilitat amb IMC elevat o arrítmies.',
      es: 'Destaca por su facilidad de manejo por enfermería y uso fuera de UCI, pero señala menor fiabilidad con IMC elevado o arritmias.',
      en: 'Notable for its ease of nursing management and use outside the ICU, but with lower reliability in patients with high BMI or arrhythmias.',
    ),
    isNew: true,
  ),
  Instrument(
