  Instrument(
    id: 'separador-langenbeck',
    name: LocalizedText(ca: 'Separador de Langenbeck', es: 'Separador de Langenbeck', en: 'Langenbeck retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Langenbeck blade retractor', 'valva de Langenbeck'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador manual rígid en forma de "L", amb una fulla plana en angle recte respecte al mànec.',
      es: 'Separador manual rígido en forma de "L", con una hoja plana en ángulo recto respecto al mango.',
      en: 'Rigid L-shaped handheld retractor with a flat blade set at a right angle to the shaft.',
    ),
    use: LocalizedText(
      ca: 'Retracció profunda de vores musculars i aponeuròtiques en laparotomies, cirurgia ortopèdica i maxil·lofacial, quan cal més profunditat que un Farabeuf.',
      es: 'Retracción profunda de bordes musculares y aponeuróticos en laparotomías, cirugía ortopédica y maxilofacial, cuando se necesita más profundidad que un Farabeuf.',
      en: 'Deep retraction of muscle and fascial edges in laparotomy, orthopedic and maxillofacial surgery, when more depth is needed than a Farabeuf provides.',
    ),
    tip: LocalizedText(
      ca: 'Existeix en diverses amplades i longituds de fulla; cal triar-la segons la profunditat de la ferida per evitar palanquejar contra l\'os.',
      es: 'Existe en distintas anchuras y longitudes de hoja; debe elegirse según la profundidad de la herida para evitar hacer palanca contra el hueso.',
      en: 'Available in several blade widths and lengths; choose according to wound depth to avoid levering against bone.',
    ),
    image: InstrumentImage(
      url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Instrumente_20120950_(1).jpg',
